    _ix: usize,
    title: SharedString,
    _window: &Window,
    _cx: &App,
) -> impl IntoElement {
    h_flex()
        .w_full()
        .h_10()
        .child(Headline::new(title).size(HeadlineSize::XSmall))
        .child(Divider::horizontal())
}

fn render_preview(
    &self,
    component: &ComponentMetadata,
    window: &mut Window,
    cx: &mut App,
) -> impl IntoElement {
    let name = component.scopeless_name();
    let scope = component.scope();

    let description = component.description();

    // Build the content container
    v_flex()
        .py_2()
        .child(
            v_flex()
                .border_1()
                .border_color(cx.theme().colors().border)
                .rounded_sm()
                .w_full()
                .gap_4()
                .py_4()
                .px_6()
                .flex_none()
                .child(
                    v_flex()
                        .gap_1()
                        .child(
                            h_flex().gap_1().text_xl().child(div().child(name)).when(
                                scope != ComponentScope::None,
                                |this| {
                                    this.child(div().opacity(0.5).child(format!("({})", scope)))
                                },
                            ),
                        )
                        .child(
                            div()
                                .text_ui_sm(cx)
                                .text_color(cx.theme().colors().text_muted)
                                .max_w(px(600.0))
                                .child(description),
                        ),
                ),
        )
        .child((component.preview())(window, cx))
        .into_any_element()
}

fn render_all_components(&self, cx: &Context<Self>) -> impl IntoElement {
    v_flex()
        .id("component-list")
        .px_8()
        .pt_4()
        .size_full()
        .child(
            if self.filtered_components().is_empty() && !self.filter_text.is_empty() {
                div()
                    .size_full()
                    .items_center()
                    .justify_center()
                    .text_color(cx.theme().colors().text_muted)
                    .child(format!("No components matching '{}'.", self.filter_text))
                    .into_any_element()
            } else {
                list(
                    self.component_list.clone(),
                    cx.processor(|this, ix, window, cx| {
                        if ix >= this.entries.len() {
                            return div().w_full().h_0().into_any_element();
                        }

                        let entry = &this.entries[ix];

                        match entry {
                            PreviewEntry::Component(component, _) => this
                                .render_preview(component, window, cx)
                                .into_any_element(),
                            PreviewEntry::SectionHeader(shared_string) => this
                                .render_scope_header(ix, shared_string.clone(), window, cx)
                                .into_any_element(),
                            PreviewEntry::AllComponents => {
                                div().w_full().h_0().into_any_element()
                            }
                            PreviewEntry::Separator => div().w_full().h_0().into_any_element(),
                        }
                    }),
                )
                .flex_grow_1()
                .with_sizing_behavior(gpui::ListSizingBehavior::Auto)
                .into_any_element()
            },
        )
}

